using System;using System.IO;using System.Collections;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using Unity.XR.CoreUtils;using UnityEngine.Rendering;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Core.Progression;
public class BulbBurstProbe:MonoBehaviour {
 string folder;int failures;WatchDemoController w;NightmareScene scene;ScareKit kit;Camera cam;Transform head;RenderPipelineAsset previous;
 public static object Begin(string folder){EditorUtility.audioMasterMute=true;Directory.CreateDirectory(folder);var p=new GameObject("Nightmare bulb pop probe").AddComponent<BulbBurstProbe>();p.folder=folder;p.StartCoroutine(p.Go());return true;}
 void Check(bool ok,string s){File.AppendAllText(folder+"/checks.txt",(ok?"PASS ":"FAIL ")+s+"\n");if(!ok)failures++;}
 void Capture(string name){cam.transform.SetPositionAndRotation(head.position,head.rotation);var rt=new RenderTexture(1100,850,24);cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1100,850,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1100,850),0,0);tex.Apply();File.WriteAllBytes(folder+"/"+name+".png",tex.EncodeToPNG());RenderTexture.active=null;cam.targetTexture=null;Destroy(tex);Destroy(rt);}
 IEnumerator Go(){
  w=FindAnyObjectByType<WatchDemoController>();scene=w.GetComponent<NightmareScene>();var rig=FindAnyObjectByType<XROrigin>();head=rig.Camera.transform;foreach(var b in rig.GetComponentsInChildren<Behaviour>(true))if(b.GetType().Name.Contains("TrackedPose")||b.GetType().Name.Contains("InputModality"))b.enabled=false;var cc=rig.GetComponent<CharacterController>();if(cc)cc.enabled=false;rig.MoveCameraToWorldLocation(new Vector3(-.4f,4.95f,1.84f));head.LookAt(LanternRoomLighting.RoomLights[2]);Physics.SyncTransforms();
  HorrorTuning.Current.nightmareEnabled=true;Check(scene.Begin(true),"Nightmare started");scene.enabled=false;var c=w.State.Scare;for(int i=0;i<200&&c.Beat!=ScareBeat.Turn;i++)c.Tick(.1f,true,true,0,0);c.Place(HorrorTuning.Current.nightmareCorner,0);kit=(ScareKit)typeof(NightmareScene).GetField("kit",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(scene);kit.Beat(ScareBeat.Turn,0);
  var t=HorrorTuning.Current;while(c.Age+.1f<t.nightmareBulbBurstAt-.05f)c.Tick(.1f,true,true,0,0);c.Tick(t.nightmareBulbBurstAt-.05f-c.Age,true,true,0,0);var bulb=GameObject.Find("Single hanging room bulb 2").GetComponentsInChildren<Renderer>().First(x=>x.name=="Weak filament bulb");var block=new MaterialPropertyBlock();int lights=FindObjectsByType<Light>(FindObjectsSortMode.None).Count(x=>x.enabled);cam=new GameObject("Burst review camera").AddComponent<Camera>();cam.enabled=false;cam.fieldOfView=65;previous=QualitySettings.renderPipeline;QualitySettings.renderPipeline=AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>("Assets/_LighthouseKeepers/Settings/RenderPipeline/QuestPipeline.asset");kit.Present(c,head.position);yield return new WaitForEndOfFrame();bulb.GetPropertyBlock(block);float before=block.GetColor("_BaseColor").maxColorComponent;Capture("before");
  c.Tick(.07f,true,true,0,0);kit.Present(c,head.position);var field=typeof(ScareKit).GetField("bulbSparks",BindingFlags.NonPublic|BindingFlags.Instance);var sparks=(ParticleSystem)field.GetValue(kit);int once=sparks?sparks.particleCount:-1;kit.Present(c,head.position);int twice=sparks?sparks.particleCount:-2;yield return new WaitForEndOfFrame();bulb.GetPropertyBlock(block);float bright=block.GetColor("_BaseColor").maxColorComponent;Capture("burst");
  Check(sparks&&sparks.GetComponent<ParticleSystemRenderer>().sharedMaterial,"Existing URP spark material is present");Check(once>0&&once<=24&&once==twice,"One bounded spark burst is emitted once ("+once+")");Check(bright>before+.25f,"F2 bulb brightens once during the burst ("+before.ToString("F2")+" to "+bright.ToString("F2")+")");Check(FindObjectsByType<Light>(FindObjectsSortMode.None).Count(x=>x.enabled)==lights,"Burst adds no realtime lights");
  c.Tick(.5f,true,true,0,0);yield return new WaitForEndOfFrame();bulb.GetPropertyBlock(block);Check(block.GetColor("_BaseColor").maxColorComponent<.1f,"Bulb returns to blackout after the brief burst");sparks.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);kit.Beat(ScareBeat.Turn,t.nightmareBulbBurstAt+.1f);kit.Present(c,head.position);Check(sparks.particleCount==0,"Late presentation does not replay an old burst");
  Check(ShaderUtil.GetShaderMessages(sparks.GetComponent<ParticleSystemRenderer>().sharedMaterial.shader).All(x=>x.severity.ToString()!="Error"),"Quest-pipeline Editor particle shader has no errors");QualitySettings.renderPipeline=previous;File.WriteAllText(folder+"/result.json","{\"passed\":"+(failures==0?"true":"false")+",\"failures\":"+failures+"}");Destroy(cam.gameObject);Destroy(gameObject);
 }
}
